queries.sql.text:
SELECT key,json_value FROM metadata ORDER BY key;
SELECT count(*) AS sample_count, sum(delta_us) AS total_delta_us, min(delta_us) AS min_delta_us, max(delta_us) AS max_delta_us FROM samples;
SELECT n.id,n.function_name,n.script_id,n.url,n.line_number,n.column_number,n.hit_count,count(s.ordinal) AS samples,sum(s.delta_us) AS attributed_delta_us,round(100.0*sum(s.delta_us)/(SELECT sum(delta_us) FROM samples),2) AS share_of_sample_deltas_pct FROM nodes n LEFT JOIN samples s ON s.node_id=n.id GROUP BY n.id ORDER BY attributed_delta_us DESC;
WITH RECURSIVE ancestry(sample_node,ancestor,depth) AS (SELECT id,id,0 FROM nodes UNION ALL SELECT a.sample_node,e.parent_id,a.depth+1 FROM ancestry a JOIN edges e ON e.child_id=a.ancestor) SELECT a.ancestor,n.function_name,n.url,n.line_number,count(s.ordinal) AS inclusive_samples,sum(s.delta_us) AS inclusive_delta_us FROM ancestry a JOIN samples s ON s.node_id=a.sample_node JOIN nodes n ON n.id=a.ancestor GROUP BY a.ancestor ORDER BY inclusive_delta_us DESC;
SELECT e.parent_id,p.function_name AS parent_function,e.child_id,c.function_name AS child_function,e.child_order FROM edges e JOIN nodes p ON p.id=e.parent_id JOIN nodes c ON c.id=e.child_id ORDER BY e.parent_id,e.child_order;
SELECT ordinal,node_id,delta_us,timestamp_us FROM samples ORDER BY ordinal;
SELECT id,raw_json FROM nodes ORDER BY id;

